  return (
    <Stack spacing={2} component="form" onSubmit={handleSubmit}>
      <TextField
        label="Email"
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        error={!!error}
        helperText={error}
        fullWidth
      />
      <Button variant="contained" type="submit">
        Submit
      </Button>
    </Stack>
  );
}
