### Pattern 2: Compound Form

```jsx
import {
  Box, TextField, Select, MenuItem, Button, 
  FormControl, InputLabel, Stack
} from '@mui/material';
import { useForm, Controller } from 'react-hook-form';

export function CompoundForm() {
  const { control, handleSubmit } = useForm({
    defaultValues: {
      name: '',
      role: '',
      email: '',
    },
  });

  return (
    <Box component="form" onSubmit={handleSubmit(onSubmit)} sx={{ maxWidth: 500 }}>
      <Stack spacing={2}>
        <Controller
          name="name"
          control={control}
          render={({ field }) => (
            <TextField {...field} label="Name" fullWidth />
          )}
        />
        <Controller
          name="role"
          control={control}
          render={({ field }) => (
            <FormControl fullWidth>
              <InputLabel>Role</InputLabel>
              <Select {...field} label="Role">
                <MenuItem value="admin">Admin</MenuItem>
                <MenuItem value="user">User</MenuItem>
              </Select>
            </FormControl>
          )}
        />
        <Button variant="contained" type="submit">
          Submit
        </Button>
      </Stack>
    </Box>
  );
}
```

### Pattern 3: Data Table with Search & Filter

```jsx
import { DataGrid } from '@mui/x-data-grid';
import { TextField, Box } from '@mui/material';
import { useState, useMemo } from 'react';

export function SearchableTable({ data, columns }) {
  const [searchText, setSearchText] = useState('');

  const filteredRows = useMemo(() => {
    return data.filter(row =>
      Object.values(row).some(val =>
        String(val).toLowerCase().includes(searchText.toLowerCase())
      )
    );
  }, [data, searchText]);

  return (
    <Box>
      <TextField
        placeholder="Search..."
        value={searchText}
        onChange={(e) => setSearchText(e.target.value)}
        sx={{ mb: 2 }}
        size="small"
      />
      <DataGrid
        rows={filteredRows}
        columns={columns}
        pageSizeOptions={[10, 25, 50]}
        sx={{ height: 600 }}
      />
    </Box>
  );
}
```

### Pattern 4: Modal with Form

```jsx
import { Dialog, DialogTitle, DialogContent, DialogActions, TextField, Button } from '@mui/material';
import { useState } from 'react';

export function EditDialog({ open, onClose, onSave, initialData }) {
  const [formData, setFormData] = useState(initialData || {});

  const handleSave = () => {
    onSave(formData);
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Edit Record</DialogTitle>
      <DialogContent sx={{ pt: 2, display: 'flex', flexDirection: 'column', gap: 2 }}>
        <TextField
          label="Name"
          value={formData.name || ''}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          fullWidth
        />
        <TextField
          label="Email"
          value={formData.email || ''}
          onChange={(e) => setFormData({ ...formData, email: e.target.value })}
          fullWidth
        />
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancel</Button>
        <Button onClick={handleSave} variant="contained">
          Save
        </Button>
      </DialogActions>
    </Dialog>
  );
}
```

### Pattern 5: Responsive Navigation Menu

```jsx
import { AppBar, Toolbar, Box, Button, IconButton, Menu, MenuItem } from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import { useState } from 'react';
import { useTheme, useMediaQuery } from '@mui/material';

export function ResponsiveNav() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [anchorEl, setAnchorEl] = useState(null);

  if (isMobile) {
    return (
      <AppBar position="static">
        <Toolbar>
          <IconButton
            onClick={(e) => setAnchorEl(e.currentTarget)}
            color="inherit"
          >
            <MenuIcon />
          </IconButton>
          <Menu
            anchorEl={anchorEl}
            open={!!anchorEl}
            onClose={() => setAnchorEl(null)}
          >
            <MenuItem>Home</MenuItem>
            <MenuItem>About</MenuItem>
            <MenuItem>Contact</MenuItem>
          </Menu>
        </Toolbar>
      </AppBar>
    );
  }

  return (
    <AppBar position="static">
      <Toolbar>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <Button color="inherit">Home</Button>
          <Button color="inherit">About</Button>
          <Button color="inherit">Contact</Button>
        </Box>
      </Toolbar>
    </AppBar>
  );
}
