interface ChannelBinding {
  id: string;
  channelType: ChannelType;
  chatId: string;
  codepilotSessionId: string;
  sdkSessionId: string;
  workingDirectory: string;
  model: string;
  mode: 'plan' | 'code' | 'ask';
  active: boolean;
  createdAt: string; // ISO string
  updatedAt: string;
}
```

